  app.post("/tabs/:tabId/locate", async (req, res) => {
    const user = owner(req),
      id = supervisor.findTab(req.params.tabId, user);
    if (typeof req.body.prompt !== "string" || !req.body.prompt.trim())
      throw problem("invalid_request", "prompt required", 400);
    res.json(
      await supervisor.run(id, user, async (w) => {
        const capture = await workerJson(
          w.socket,
          supervisor.config.workerKey,
          "POST",
          "/internal/capture",
          { tabId: req.params.tabId },
        );
        const result = await locate(config, capture, req.body.prompt);
        const observationId = randomUUID();
        supervisor.observations.set(observationId, {
          sessionId: id,
          tabId: req.params.tabId,
          captureId: capture.captureId,
          boxes: result.boxes,
          created: Date.now(),
        });
        return {
          observationId,
          tabId: req.params.tabId,
          width: capture.width,
          height: capture.height,
          ...result,
          nextAction: result.boxes.length
            ? "Inspect the image, then call camofox_click_target with the selected targetNumber."
            : "No matches. Refine the prompt or scroll and locate again.",
        };
      }),
    );
  });
