  app.post('/tabs/:tabId/capture-sequence', async (req,res) => {
    const user=owner(req),tabId=req.params.tabId;
    const sessionId=supervisor.findTab(tabId,user,req.body.idempotencyKey);
    const session=supervisor.store.checkOwner(sessionId,user);
    const profileDir=join(config.stateDir,'profiles',session.profileId);
    const previous=req.body.sequenceId ? readSequence(profileDir,req.body.sequenceId,sessionId) : null;
    const options=previous ? previous.options : captureOptions(req.body.options);
    const args={tabId,...(previous?{sequenceId:previous.sequenceId}:{options})};
    const response=await supervisor.submitOperation(sessionId,user,{kind:'capture_sequence',tabId,
      validate:()=>{
        if(previous){
          if(previous.tabId!==tabId)throw problem('invalid_request','Resume requires the original logical tab',400);
          // A queued/active sequence cannot be resumed concurrently, even if a
          // new retry key is supplied. The existing operation must settle first.
          try{if(!terminalOperation(supervisor.operations.get(previous.operationId).state))throw problem('session_busy','Capture sequence is still running; inspect or cancel its operation');}
          catch(e){if(e.code!=='operation_not_found')throw e;}
        }
      }},args,req.body.idempotencyKey,
      (w,operation)=>workerRequest(w.socket,supervisor.config.workerKey,'POST','/internal/capture-sequence',
        {tabId,sequenceId:previous?.sequenceId||operation.id,resume:!!previous,options:previous?undefined:options},operation),options.budgetMs);
    res.status(response.status).type(response.type).send(response.bytes);
  });
