  app.get('/agent-sessions/:sessionId/capture-sequences/:sequenceId', (req,res) => {
    const session=supervisor.store.checkOwner(req.params.sessionId,owner(req));
    const manifest=readSequence(join(config.stateDir,'profiles',session.profileId),req.params.sequenceId,session.id);
    const sequence=sequenceSummary(manifest);
    if(sequence.state==='running'){
      try{const op=supervisor.operations.get(sequence.operationId);if(terminalOperation(op.state)){sequence.state='interrupted';sequence.reason=op.errorCode||'operation_result_unavailable';}}
      catch(e){if(e.code!=='operation_not_found')throw e;sequence.state='interrupted';sequence.reason='operation_result_unavailable';}
    }
    res.json({sequence});
  });
