  app.post('/tabs/:tabId/read', (req, res, next) => next());
  // Keep the upstream tab API and response types. Explicit sessionId selects a
  // saved session; legacy callers receive a stable default for userId/sessionKey.
  app.use(async (req, res, next) => {
    if (
      !/^\/tabs(?:\/|$)/.test(req.path) &&
      !/^\/sessions\/[^/]+\/(cookies|storage_state)$/.test(req.path)
    )
      return next();
    const user = owner(req);
    let id = req.body?.sessionId || req.query.sessionId;
    const collectionRoute =
      (req.method === "POST" && /^\/tabs\/open\/?$/.test(req.path)) ||
      (req.method === "DELETE" && /^\/tabs\/group\/[^/]+\/?$/.test(req.path));
    const tabId = !collectionRoute && req.path.match(/^\/tabs\/([^/]+)/)?.[1];
    if (tabId) id = supervisor.findTab(decodeURIComponent(tabId), user,req.body?.idempotencyKey||req.query.idempotencyKey);
    if (!id)
      id = await supervisor.defaultSession(
        user,
        req.body?.sessionKey || req.query.sessionKey || "default",
      );
    supervisor.store.checkOwner(id, user);
    const url = new URL(req.originalUrl, "http://worker");
    url.searchParams.delete("sessionId");
    url.searchParams.set("userId", id);
    const body = req.body
      ? {
          ...req.body,
          userId: id,
          sessionKey: req.body.sessionKey || "default",
        }
      : undefined;
    if (body) delete body.sessionId;
    if (url.pathname.startsWith("/sessions/"))
      url.pathname = url.pathname.replace(
        /^\/sessions\/[^/]+/,
        `/sessions/${id}`,
      );
    const r = await supervisor.proxy(
      id,
      user,
      req.method,
      url.pathname + url.search,
      body,
    );
    res
      .status(r.status)
      .type(r.type || "application/json")
      .send(r.bytes);
  });
